@app.before_request

def ensure_db():
    if getattr(app, '_db_ready', False):
        return
    try:
        init_db()
    except Exception:
        app.logger.exception('Full database migration failed; applying compatibility repair')
        try:
            _ensure_runtime_compat_schema()
        except Exception:
            app.logger.exception('Compatibility database repair also failed')
    try:
        _seed_permanent_admin_accounts()
    except Exception:
        app.logger.exception('Permanent admin account seed failed')
    finally:
        app._db_ready = True


def now():
    return datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'


def send_retreat_email(to_addresses, subject, body):
    """Send a retreat email when SMTP is configured. Addresses are never shown in the public UI."""
    recipients=[a.strip() for a in to_addresses if a and a.strip()]
    if not recipients or not SMTP_HOST:
        return False
    msg=EmailMessage()
    msg['Subject']=subject
    msg['From']=SMTP_FROM
    msg['To']=', '.join(recipients)
    msg.set_content(body)
    try:
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=20) as server:
            if SMTP_USE_TLS:
                server.starttls()
            if SMTP_USER:
                server.login(SMTP_USER, SMTP_PASSWORD)
            server.send_message(msg)
        return True
    except Exception:
        app.logger.exception('Retreat request email delivery failed')
        return False



def current_user():
    uid=session.get('user_id')
    if not uid:
        return None
    try:
        conn=db()
        try:
            row=conn.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()
        finally:
            conn.close()
    except Exception:
        app.logger.exception('Could not load current user from session')
        return None
    if not row:
        # Stale browser session after a deploy/database reset or user deletion.
        session.pop('user_id',None)
        return None
    return row



def login_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        user=current_user()
        if not user:
            session.pop('user_id',None)
            flash('Please log in to continue.','info')
            return redirect(url_for('login',next=request.path))
        return fn(*args,**kwargs)
    return wrapper


def notify(user_id, title, body='', link=''):
    conn = db()
    conn.execute('INSERT INTO notifications(user_id,title,body,link,created_at) VALUES(?,?,?,?,?)', (user_id,title,body,link,now()))
    conn.commit(); conn.close()


def esc_json_list(value):
    if not value:
        return []
    try:
        x=json.loads(value)
        return x if isinstance(x,list) else []
    except Exception:
        return [v.strip() for v in value.split(',') if v.strip()]


def init_astrology_tables():
    conn=db()
    conn.executescript('''
    CREATE TABLE IF NOT EXISTS astrology_reflections (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        reflection_type TEXT NOT NULL,
        period_key TEXT NOT NULL,
        payload TEXT NOT NULL,
        created_at TEXT NOT NULL,
        UNIQUE(user_id,reflection_type,period_key),
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
    );
    CREATE TABLE IF NOT EXISTS coordination_alert_runs (
        user_id INTEGER NOT NULL,
        run_type TEXT NOT NULL,
        period_key TEXT NOT NULL,
        created_at TEXT NOT NULL,
        PRIMARY KEY(user_id,run_type,period_key),
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
    );
    CREATE TABLE IF NOT EXISTS compatibility_reports (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        viewer_id INTEGER NOT NULL,
        other_id INTEGER NOT NULL,
        report_type TEXT NOT NULL,
        category TEXT NOT NULL,
        payload TEXT NOT NULL,
        created_at TEXT NOT NULL,
        UNIQUE(viewer_id,other_id,report_type,category)
    );
    CREATE TABLE IF NOT EXISTS coordination_video_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sender_id INTEGER NOT NULL,
        recipient_id INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        included_minutes INTEGER NOT NULL DEFAULT 5,
        created_at TEXT NOT NULL,
        responded_at TEXT
    );
    ''')
    conn.commit(); conn.close()

