def save_community_media(file_storage, user_id):
    if not file_storage or not getattr(file_storage, 'filename', ''):
        return '', ''
    name = secure_filename(file_storage.filename)
    ext = Path(name).suffix.lower()
    image_ext = {'.jpg','.jpeg','.png','.gif','.webp'}
    video_ext = {'.mp4','.mov','.webm','.m4v'}
    if ext not in image_ext | video_ext:
        return '', ''
    stamp = datetime.utcnow().strftime('%Y%m%d%H%M%S%f')
    stored = f'u{user_id}_{stamp}{ext}'
    file_storage.save(UPLOAD_DIR / stored)
    return stored, ('video' if ext in video_ext else 'image')


def community_media_html(post):
    name = post['media_name'] if 'media_name' in post.keys() else ''
    kind = post['media_type'] if 'media_type' in post.keys() else ''
    if not name:
        return ''
    src = url_for('community_media', filename=name)
    if kind == 'video':
        return f'<video class="media" controls preload="metadata" style="width:100%;max-height:520px"><source src="{src}"></video>'
    return f'<img class="media" src="{src}" alt="Community post media" style="width:100%;max-height:520px;object-fit:cover">'


def journal_category_for_public(category):
    return category if category in JOURNAL_CATEGORIES else 'Reflection'


def public_journal_cards(member_id, viewer_id=None):
    conn=db(); posts=conn.execute('SELECT p.*,u.name FROM community_posts p JOIN users u ON u.id=p.user_id WHERE p.user_id=? ORDER BY p.id DESC',(member_id,)).fetchall(); conn.close()
    if not posts:
        return '<div class="empty"><h3>No Public Journal entries yet</h3><p class="muted">Community posts shared by this member will appear here.</p></div>'
    cards=[]
    for p in posts:
        message=f'<a class="out" href="{url_for("message_member",recipient_id=p["user_id"],origin="Community",post_id=p["id"])}">Send Message</a>' if viewer_id else ''
        if viewer_id == p['user_id']:
            controls=message+f'<a class="out" href="{url_for("community_post_edit",post_id=p["id"])}">Edit Post</a><form method="post" action="{url_for("community_post_delete",post_id=p["id"])}" style="display:inline"><button class="out danger" type="submit">Delete Post</button></form>'
        else:
            controls=message
        cards.append(f'<article class="card"><span class="badge">{p["category"]}</span><h3>{p["title"]}</h3><p class="muted small">{p["created_at"]}</p><p>{p["body"]}</p>{community_media_html(p)}<div class="actions">{controls}</div></article>')
    return ''.join(cards)


