# Astrology + Conscious Coordination engine
# -----------------------------------------------------------------------------
ZODIAC_SIGNS=('Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces')
PLANET_NAMES=('Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn')

def _sign_from_longitude(lon):
    lon=float(lon)%360.0; idx=int(lon//30)
    return ZODIAC_SIGNS[idx], round(lon-(idx*30),2)

def _astrology_provider(action,payload=None):
    if not ASTROLOGY_PROVIDER_URL: return None
    data=json.dumps({'action':action,**(payload or {})}).encode('utf-8')
    headers={'Content-Type':'application/json','User-Agent':'The-Seasons-Within/1.0'}
    if ASTROLOGY_PROVIDER_KEY: headers['Authorization']='Bearer '+ASTROLOGY_PROVIDER_KEY
    try:
        req=urllib.request.Request(ASTROLOGY_PROVIDER_URL,data=data,headers=headers,method='POST')
        with urllib.request.urlopen(req,timeout=20) as r: return json.loads(r.read().decode('utf-8'))
    except Exception: return None

def current_sky_data():
    ext=_astrology_provider('current_sky',{'utc':datetime.utcnow().replace(microsecond=0).isoformat()+'Z'})
    if ext and ext.get('planets'):
        ext['source']=ext.get('source') or 'configured astrology provider'; return ext
    try:
        import swisseph as swe
        n=datetime.utcnow(); jd=swe.julday(n.year,n.month,n.day,n.hour+n.minute/60+n.second/3600)
        ids={'Sun':swe.SUN,'Moon':swe.MOON,'Mercury':swe.MERCURY,'Venus':swe.VENUS,'Mars':swe.MARS,'Jupiter':swe.JUPITER,'Saturn':swe.SATURN}
        planets={}
        for name,pid in ids.items():
            lon=float(swe.calc_ut(jd,pid)[0][0])%360; sign,degree=_sign_from_longitude(lon)
            planets[name]={'longitude':round(lon,3),'sign':sign,'degree':degree}
        phase=(planets['Moon']['longitude']-planets['Sun']['longitude'])%360
        names=('New Moon','Waxing Crescent','First Quarter','Waxing Gibbous','Full Moon','Waning Gibbous','Last Quarter','Waning Crescent')
        phase_name=names[int(((phase+22.5)%360)//45)]
        return {'utc':n.replace(microsecond=0).isoformat()+'Z','planets':planets,'lunar_phase':phase_name,'source':'Swiss Ephemeris runtime'}
    except Exception:
        return {'utc':datetime.utcnow().replace(microsecond=0).isoformat()+'Z','planets':{},'lunar_phase':'','source':'astrology provider not configured'}


def member_chart_data(member):
    if not member or not member['dob'] or not member['birth_city'] or not member['birth_country']:
        return {'ready':False,'reason':'Birth setup is incomplete.'}
    birth={'date':member['dob'],'time':member['birth_time'] or '','exact_time':bool(member['exact_time']),'city':member['birth_city'] or '','region':member['birth_region'] or '','country':member['birth_country'] or ''}
    data=_astrology_provider('natal_chart',{'birth':birth})
    if data and data.get('planets'):
        data['ready']=True; data['birth']=birth; data['source']=data.get('source') or 'configured planetary provider'; return data
    local=_local_natal_planets(member)
    if local: return local
    return {'ready':False,'reason':'Planetary calculation is waiting for a supported time-zone calculation.','birth':birth}



def _valid_timezone_name(name):
    if not name:
        return ''
    try:
        ZoneInfo(str(name))
        return str(name)
    except Exception:
        return ''


def _cache_birth_timezone(member, tzname):
    tzname=_valid_timezone_name(tzname)
    if not tzname or not member:
        return tzname
    try:
        uid=member['id']
    except Exception:
        return tzname
    try:
        conn=db()
        conn.execute("UPDATE users SET birth_timezone=? WHERE id=?",(tzname,uid))
        conn.commit(); conn.close()
    except Exception:
        app.logger.exception('Could not cache resolved birth timezone')
    return tzname


def _birth_place_coordinates(member):
    city=(member['birth_city'] or '').strip()
    region=(member['birth_region'] or '').strip()
    country=(member['birth_country'] or '').strip()
    if not city or not country:
        return None
    query=', '.join(x for x in [city,region,country] if x)
    try:
        params=urllib.parse.urlencode({'q':query,'format':'jsonv2','limit':1,'addressdetails':1})
        req=urllib.request.Request(
            'https://nominatim.openstreetmap.org/search?'+params,
            headers={'User-Agent':'TheSeasonsWithin/1.0 (contact: e.reed81@gmail.com)','Accept':'application/json'}
        )
        with urllib.request.urlopen(req,timeout=8) as resp:
            data=json.loads(resp.read().decode('utf-8'))
        if data:
            return float(data[0]['lat']),float(data[0]['lon'])
    except Exception:
        app.logger.info('Birth-place geocoding was unavailable for %s',query)
    return None


def _timezone_from_coordinates(lat,lon):
    # TimeAPI returns an IANA timezone for a latitude/longitude. We validate
    # the returned name with ZoneInfo before using it.
    endpoints=[
        'https://timeapi.io/api/TimeZone/coordinate',
        'https://www.timeapi.io/api/TimeZone/coordinate',
    ]
    params=urllib.parse.urlencode({'latitude':lat,'longitude':lon})
    for base in endpoints:
        try:
            req=urllib.request.Request(base+'?'+params,headers={'User-Agent':'TheSeasonsWithin/1.0','Accept':'application/json'})
            with urllib.request.urlopen(req,timeout=8) as resp:
                data=json.loads(resp.read().decode('utf-8'))
            for key in ('timeZone','timezone','timeZoneId','timezoneId','id'):
                tz=_valid_timezone_name(data.get(key) if isinstance(data,dict) else '')
                if tz:
                    return tz
        except Exception:
            continue
    return ''


