def _birth_timezone(member):
    if not member:
        return None
    try:
        cached=member['birth_timezone'] if 'birth_timezone' in member.keys() else ''
    except Exception:
        cached=''
    cached=_valid_timezone_name(cached)
    if cached:
        return cached

    country=(member['birth_country'] or '').strip()
    region=(member['birth_region'] or '').strip()
    city=(member['birth_city'] or '').strip()

    # Fast local fallback first for known cities/regions.
    tz=_valid_timezone_name(_regional_timezone_fallback(country,region,city))
    if tz:
        return _cache_birth_timezone(member,tz)

    coords=_birth_place_coordinates(member)
    if coords:
        tz=_valid_timezone_name(_timezone_from_coordinates(*coords))
        if not tz:
            tz=_valid_timezone_name(_regional_timezone_fallback(country,region,city,coords))
        if tz:
            return _cache_birth_timezone(member,tz)

    return None


def _local_natal_planets(member):
    tzname=_birth_timezone(member)
    if not tzname:
        return None
    try:
        import swisseph as swe

        # If birth time is unknown, calculate the core planets at local noon.
        # Rising/houses are deliberately withheld. This keeps the core
        # Conscious Coordination layer available without inventing a birth time.
        time_unknown=not bool(member['birth_time'])
        local_time=member['birth_time'] or '12:00'
        local=datetime.strptime(member['dob']+' '+local_time,'%Y-%m-%d %H:%M').replace(tzinfo=ZoneInfo(tzname))
        utc=local.astimezone(timezone.utc)
        jd=swe.julday(utc.year,utc.month,utc.day,utc.hour+utc.minute/60+utc.second/3600)

        ids={'Sun':swe.SUN,'Moon':swe.MOON,'Mercury':swe.MERCURY,'Venus':swe.VENUS,
             'Mars':swe.MARS,'Jupiter':swe.JUPITER,'Saturn':swe.SATURN}
        planets={}
        for name,pid in ids.items():
            lon=float(swe.calc_ut(jd,pid)[0][0])%360
            sign,degree=_sign_from_longitude(lon)
            planets[name]={'longitude':round(lon,3),'sign':sign,'degree':degree}

        # When time is unknown, identify whether the Moon changes sign during
        # the local calendar day. If so, show the noon calculation but flag it
        # as time-sensitive rather than pretending the sign is certain.
        moon_time_sensitive=False
        if time_unknown:
            start_local=datetime.strptime(member['dob']+' 00:00','%Y-%m-%d %H:%M').replace(tzinfo=ZoneInfo(tzname))
            end_local=datetime.strptime(member['dob']+' 23:59','%Y-%m-%d %H:%M').replace(tzinfo=ZoneInfo(tzname))
            signs=[]
            for dt in (start_local,end_local):
                z=dt.astimezone(timezone.utc)
                j=swe.julday(z.year,z.month,z.day,z.hour+z.minute/60)
                mlon=float(swe.calc_ut(j,swe.MOON)[0][0])%360
                signs.append(_sign_from_longitude(mlon)[0])
            moon_time_sensitive=(signs[0]!=signs[1])
            if moon_time_sensitive:
                planets['Moon']['time_sensitive']=True

        return {
            'ready':True,
            'planets':planets,
            'source':'Swiss Ephemeris local calculation',
            'timezone':tzname,
            'time_approximate':time_unknown,
            'moon_time_sensitive':moon_time_sensitive,
            'birth':{
                'date':member['dob'],
                'time':member['birth_time'] or '',
                'exact_time':bool(member['exact_time']),
                'city':member['birth_city'],
                'region':member['birth_region'],
                'country':member['birth_country']
            }
        }
    except Exception:
        app.logger.exception('Local natal planetary calculation failed')
        return None

def _split_choices(v):
    return {x.strip().lower() for x in re.split(r'[,|;/]+',v or '') if x.strip()}



def member_coordination_scores(user, cp_row):
    """Self-reported coordination indicators for a single member.

    These are profile-based indicators, not clinical scores and not two-person
    compatibility. They summarize how complete/consistent the member's selected
    approaches are across the Conscious Coordination questionnaire.
    """
    cp=dict(cp_row) if cp_row else {}

    def choices(key):
        return _split_choices(cp.get(key,''))

    def answered(*keys):
        return sum(1 for k in keys if choices(k) or (cp.get(k,'') or '').strip())

    def score_group(keys, supportive=None, base=58):
        total=max(1,len(keys))
        completion=answered(*keys)/total
        score=base + round(completion*24)
        if supportive:
            hits=0
            possible=0
            for key,opts in supportive.items():
                selected=choices(key)
                if selected:
                    possible+=1
                    if selected & {x.lower() for x in opts}:
                        hits+=1
            if possible:
                score += round((hits/possible)*10)
        return max(35,min(96,score))

    metrics=[
        ('Social & Emotional Intelligence',score_group(
            ['other_emotions','regulate','overwhelmed'],
            {'other_emotions':['listen first','ask what they need','give space when requested'],
             'regulate':['quiet time','movement / exercise','nature','breathing / meditation','talking with someone i trust','music / creative activity','rest']},
            56)),
        ('Communication',score_group(
            ['communication'],
            {'communication':['direct but gentle','thoughtful and measured','warm and expressive','need time to process first']},
            58)),
        ('Conflict',score_group(
            ['conflict_style'],
            {'conflict_style':['talk it through calmly','prefer direct resolution','seek compromise','need time before discussing']},
            54)),
        ('Repair & Accountability',score_group(
            ['repair'],
            {'repair':['apologize directly','need actions to match words','talk through what happened','focus on solutions','give space then reconnect']},
            56)),
        ('Emotional Rhythm',score_group(
            ['overwhelmed','regulate','other_emotions'],None,56)),
        ('Love Languages / Affection',score_group(
            ['affection'],None,60)),
        ('Lifestyle & Values',score_group(
            ['lifestyle','values_text','family'],None,58)),
        ('Boundaries',score_group(
            ['boundaries','trust'],
            {'boundaries':['clear verbal boundaries','need advance notice / planning','value privacy and alone time','flexible with communication'],
             'trust':['consistency','honesty','time','shared experiences','emotional openness','reliability']},
            56)),
        ('Business Collaboration',score_group(
            ['business_style'],None,58)),
    ]

    chart=member_chart_data(user)
    if chart.get('ready'):
        planet_count=sum(1 for p in PLANET_NAMES if (chart.get('planets') or {}).get(p))
        planetary=max(60,min(96,60+planet_count*5))
    else:
        planetary=60
    metrics.append(('Planetary Coordination',planetary))

    overall=round(sum(score for _,score in metrics)/len(metrics)) if metrics else 0
    return {'overall':overall,'metrics':metrics}

def basic_compatibility(me_id,other_id,kind='general'):
    conn=db()
    arow=conn.execute('SELECT * FROM connection_profiles WHERE user_id=?',(me_id,)).fetchone()
    brow=conn.execute('SELECT * FROM connection_profiles WHERE user_id=?',(other_id,)).fetchone()
    au=conn.execute('SELECT * FROM users WHERE id=?',(me_id,)).fetchone()
    bu=conn.execute('SELECT * FROM users WHERE id=?',(other_id,)).fetchone()
    conn.close()
    if not au or not bu:
        return {'ready':False,'reason':'Member profile is not available.'}
    a=dict(arow) if arow else {}
    b=dict(brow) if brow else {}

    def choice_score(keys):
        vals=[]
        for k in keys:
            av=_split_choices(a.get(k,''))
            bv=_split_choices(b.get(k,''))
            if av and bv:
                vals.append(round(100*len(av & bv)/max(1,len(av | bv))))
        return round(sum(vals)/len(vals)) if vals else None

    groups=[
        ('Social & Emotional Intelligence',['other_emotions','regulate','overwhelmed']),
        ('Communication',['communication']),
        ('Conflict',['conflict_style']),
        ('Repair & Accountability',['repair']),
        ('Emotional Rhythm',['regulate','overwhelmed','other_emotions']),
        ('Love Languages / Affection',['affection']),
        ('Lifestyle & Values',['lifestyle','values_text','family']),
        ('Boundaries',['boundaries','trust']),
        ('Psychology-Oriented Compatibility',['communication','conflict_style','repair','boundaries','trust']),
    ]
    metrics=[]
    for label,keys in groups:
        score=choice_score(keys)
        if score is not None:
            metrics.append({'area':label,'score':score})

    ca=member_chart_data(au); cb=member_chart_data(bu)
    if ca.get('ready') and cb.get('ready'):
        elements={'Aries':'Fire','Leo':'Fire','Sagittarius':'Fire','Taurus':'Earth','Virgo':'Earth','Capricorn':'Earth',
                  'Gemini':'Air','Libra':'Air','Aquarius':'Air','Cancer':'Water','Scorpio':'Water','Pisces':'Water'}
        complementary={('Fire','Air'),('Air','Fire'),('Earth','Water'),('Water','Earth')}
        vals=[]
        for planet in PLANET_NAMES:
            pa=(ca.get('planets') or {}).get(planet,{})
            pb=(cb.get('planets') or {}).get(planet,{})
            sa,sb=pa.get('sign'),pb.get('sign')
            if not sa or not sb: continue
            if sa==sb: vals.append(100)
            else:
                ea,eb=elements.get(sa),elements.get(sb)
                if ea and eb: vals.append(82 if ea==eb else 72 if (ea,eb) in complementary else 48)
        if vals:
            metrics.append({'area':'Planetary Coordination','score':round(sum(vals)/len(vals))})

    scores=[m['score'] for m in metrics]
    overall=round(sum(scores)/len(scores)) if scores else None
    level='Complete More Profile Details' if overall is None else ('Strong Alignment' if overall>=70 else 'Worth Exploring' if overall>=45 else 'Needs Conversation')
    ordered=sorted(metrics,key=lambda x:x['score'],reverse=True)
    strength=ordered[0]['area'] if ordered else 'Complete more profile information'
    difference=ordered[-1]['area'] if len(ordered)>1 else 'More information will make this clearer'
    starter=(f"Your strongest current alignment is {strength}. What does that look like in real life for each of you?"
             if ordered else "What helps each of you feel understood and respected when getting to know someone?")
    return {'ready':True,'member':bu['name'],'kind':kind,'score':overall,'level':level,'metrics':metrics,
            'strength':strength,'difference':difference,'conversation_starter':starter}

def _openai_text(prompt):
    if not OPENAI_API_KEY: return None
    payload={'model':ASTROLOGY_AI_MODEL,'input':prompt,'store':False}
    try:
        req=urllib.request.Request('https://api.openai.com/v1/responses',data=json.dumps(payload).encode('utf-8'),headers={'Authorization':'Bearer '+OPENAI_API_KEY,'Content-Type':'application/json'},method='POST')
        with urllib.request.urlopen(req,timeout=45) as r: data=json.loads(r.read().decode('utf-8'))
        parts=[]
        for item in data.get('output',[]):
            for c in item.get('content',[]):
                if c.get('type')=='output_text' and c.get('text'): parts.append(c['text'])
        return '\n'.join(parts).strip() or None
    except Exception: return None


REFLECTION_ENGINE_VERSION = 4

def _angle_distance(a,b):
    try:
        d=abs(float(a)-float(b))%360
        return min(d,360-d)
    except Exception:
        return None

def _chart_sky_aspects(chart,sky):
    """Calculate a small factual transit-to-natal aspect layer from supplied longitudes."""
    natal=(chart or {}).get('planets') or {}
    current=(sky or {}).get('planets') or {}
    aspects=[
        ('conjunction',0,7),
        ('sextile',60,4),
        ('square',90,5),
        ('trine',120,5),
        ('opposition',180,6),
    ]
    found=[]
    for sky_name,sp in current.items():
        slon=sp.get('longitude')
        if slon is None:
            continue
        for natal_name,np in natal.items():
            nlon=np.get('longitude')
            if nlon is None:
                continue
            dist=_angle_distance(slon,nlon)
            if dist is None:
                continue
            for aspect,target,orb in aspects:
                delta=abs(dist-target)
                if delta<=orb:
                    found.append({
                        'current_planet':sky_name,
                        'natal_planet':natal_name,
                        'aspect':aspect,
                        'orb':round(delta,2),
                        'current_sign':sp.get('sign',''),
                        'current_degree':sp.get('degree',''),
                        'natal_sign':np.get('sign',''),
                        'natal_degree':np.get('degree',''),
                    })
                    break
    priority={'Moon':0,'Mercury':1,'Venus':2,'Mars':3,'Sun':4,'Jupiter':5,'Saturn':6}
    found.sort(key=lambda x:(priority.get(x['current_planet'],9),x['orb']))
    return found[:10]

def _member_wellness_practices(profile):
    p=profile or {}
    raw=' , '.join(str(p.get(k,'') or '') for k in ('regulate','lifestyle','seeking')).lower()
    mapping=[
        ('meditation',['meditation','breathing / meditation','breathwork']),
        ('yoga',['yoga']),
        ('movement',['movement / exercise','fitness','exercise']),
        ('nature',['nature','outdoors']),
        ('quiet time',['quiet time','homebody / quiet time']),
        ('journaling',['journal','journaling','writing']),
        ('music or sound',['music / creative activity','music','sound healing']),
        ('Reiki',['reiki']),
        ('rest',['rest']),
        ('trusted conversation',['talking with someone i trust']),
    ]
    selected=[]
    for label,needles in mapping:
        if any(n in raw for n in needles):
            selected.append(label)
    return selected[:5]

