def plan_text_to_html(text):
    if not text: return ''
    parts=[]
    for raw in text.splitlines():
        line=raw.strip()
        if not line: continue
        if line.startswith('# '): parts.append(f'<h1>{html.escape(line[2:])}</h1>')
        elif line.startswith('## '): parts.append(f'<h2>{html.escape(line[3:])}</h2>')
        elif line.startswith('### '): parts.append(f'<h3>{html.escape(line[4:])}</h3>')
        elif line.startswith(('- ','• ')): parts.append(f'<p>• {html.escape(line[2:])}</p>')
        else: parts.append(f'<p>{html.escape(line)}</p>')
    return '<article class="card" style="max-width:900px;margin:16px auto;line-height:1.75">'+''.join(parts)+'</article>'

def _openai_output_text(data):
    if isinstance(data,dict) and data.get('output_text'): return data['output_text']
    chunks=[]
    for item in (data.get('output',[]) if isinstance(data,dict) else []):
        for c in item.get('content',[]):
            if isinstance(c,dict) and c.get('text'): chunks.append(c['text'])
    return '\n'.join(chunks).strip()

def generate_business_plan_ai(answers):
    if not OPENAI_API_KEY: return None, 'AI generation is not configured. Add OPENAI_API_KEY in Render environment settings.'
    prompt='''You are a senior business-plan consultant. Create a REAL, professional, investor/lender-ready business plan using ONLY the member answers below. Do not invent factual revenue history, licenses, customer counts, addresses, funding commitments, certifications, or market research. Clearly label reasonable projections or assumptions as projections/assumptions. Target approximately 5,000–6,500 substantive words so the professionally formatted document is typically 10–15 pages. Use Markdown headings. Include: Executive Summary; Company Description; Founder/Business Background where supported; Mission; Vision; Core Values; Products & Services; Customer Problem & Business Solution; Target Market; Market Overview and Competitive Analysis (with careful assumptions if exact competitors were not supplied); Unique Selling Proposition; Marketing Strategy; Sales Strategy; Operations Plan; Management/Organization; Technology and Hosted App Strategy; Certifications & Compliance; Startup/Growth Requirements; Pricing and Revenue Model; Financial Strategy; Startup/Growth Budget; Cash Flow and Break-even Planning guidance; Funding Strategy; Short-Term Goals; Long-Term Goals; Risks & Challenges; 90-Day Action Priorities; and Conclusion. Also include a concise MARKETING STRATEGY section and a detailed 90-DAY LAUNCH PLAN section that can be extracted separately. Write in professional prose, not questionnaire format.\n\nMEMBER ANSWERS:\n'''+json.dumps(answers,indent=2)
    payload=json.dumps({'model':BUSINESS_PLAN_AI_MODEL,'input':prompt}).encode('utf-8')
    req=urllib.request.Request('https://api.openai.com/v1/responses',data=payload,headers={'Authorization':'Bearer '+OPENAI_API_KEY,'Content-Type':'application/json'},method='POST')
    try:
        with urllib.request.urlopen(req,timeout=180) as resp: data=json.loads(resp.read().decode('utf-8'))
        text=_openai_output_text(data)
        if not text: return None,'AI returned no plan text.'
        return text,None
    except Exception as e:
        return None,'AI generation failed. Check API configuration and try again.'

def extract_plan_subsection(text, heading, next_heading=None):
    if not text: return ''
    low=text.lower(); start=low.find(heading.lower())
    if start<0: return ''
    end=len(text)
    if next_heading:
        p=low.find(next_heading.lower(),start+len(heading))
        if p>=0: end=p
    return text[start:end].strip()

def build_simple_pdf(title, text):
    # Dependency-free text PDF: readable plan with automatic pages.
    width,height=612,792; left=54; top=738; bottom=54; font_size=11; leading=16; max_chars=82
    paragraphs=[]
    for line in text.splitlines():
        stripped=line.strip()
        if not stripped: paragraphs.append(''); continue
        prefix=''
        if stripped.startswith('#'): stripped=stripped.lstrip('#').strip().upper()
        wrapped=textwrap.wrap(stripped,width=max_chars,break_long_words=False,break_on_hyphens=False) or ['']
        paragraphs.extend(wrapped); paragraphs.append('')
    pages=[]; cur=[]; y=top
    for line in [title.upper(),'']+paragraphs:
        if y<bottom+leading:
            pages.append(cur); cur=[]; y=top
        cur.append((left,y,line)); y-=leading
    if cur: pages.append(cur)
    # PDF object builder, Helvetica only.
    objs=[]
    def add(obj): objs.append(obj); return len(objs)
    font_id=add(b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')
    page_ids=[]; content_ids=[]
    for page in pages:
        cmds=['BT','/F1 11 Tf']
        for x,y,line in page:
            esc=line.replace('\\','\\\\').replace('(','\\(').replace(')','\\)').encode('latin-1','replace').decode('latin-1')
            cmds.append(f'1 0 0 1 {x} {y} Tm ({esc}) Tj')
        cmds.append('ET'); stream='\n'.join(cmds).encode('latin-1','replace')
        content_ids.append(add(b'<< /Length '+str(len(stream)).encode()+b' >>\nstream\n'+stream+b'\nendstream'))
        page_ids.append(add(b''))
    pages_id=add(b'')
    for idx,pid in enumerate(page_ids):
        objs[pid-1]=f'<< /Type /Page /Parent {pages_id} 0 R /MediaBox [0 0 {width} {height}] /Resources << /Font << /F1 {font_id} 0 R >> >> /Contents {content_ids[idx]} 0 R >>'.encode()
    kids=' '.join(f'{pid} 0 R' for pid in page_ids)
    objs[pages_id-1]=f'<< /Type /Pages /Kids [{kids}] /Count {len(page_ids)} >>'.encode()
    catalog_id=add(f'<< /Type /Catalog /Pages {pages_id} 0 R >>'.encode())
    data=bytearray(b'%PDF-1.4\n'); offsets=[0]
    for i,obj in enumerate(objs,1):
        offsets.append(len(data)); data.extend(f'{i} 0 obj\n'.encode()); data.extend(obj); data.extend(b'\nendobj\n')
    xref=len(data); data.extend(f'xref\n0 {len(objs)+1}\n'.encode()); data.extend(b'0000000000 65535 f \n')
    for off in offsets[1:]: data.extend(f'{off:010d} 00000 n \n'.encode())
    data.extend(f'trailer\n<< /Size {len(objs)+1} /Root {catalog_id} 0 R >>\nstartxref\n{xref}\n%%EOF'.encode())
    return bytes(data)


