@app.route('/business-development', methods=['GET','POST'])
@login_required
def startup():
    u=current_user(); conn=db(); saved=conn.execute('SELECT payload FROM business_plan_intake WHERE user_id=?',(u['id'],)).fetchone(); conn.close(); data=json.loads(saved['payload']) if saved else {}
    if request.method=='POST':
        fields=['name','email','phone','preferred_contact','business_name','business_type','industry','business_stage','mission','vision','core_values','usp','short_goals','long_goals','challenges','plan_goal','financial_records','budget','revenue_sources','financial_help','target_audience','marketing_strategy','marketing_help','certification_need','certifications','grant_interest','funding_type','additional_info','heard_about']
        payload={k:request.form.get(k,'').strip() for k in fields}; action=request.form.get('action','save')
        conn=db(); conn.execute('''INSERT INTO business_plan_intake(user_id,payload,updated_at) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET payload=excluded.payload,updated_at=excluded.updated_at''',(u['id'],json.dumps(payload),now())); conn.commit(); conn.close()
        if action=='generate': return redirect(url_for('business_plan_generate'))
        flash('Business Plan questionnaire saved. You can return and continue later.','success'); return redirect(url_for('startup'))
    def v(k): return html.escape(str(data.get(k,'') or ''),quote=True)
    def helpbox(desc,example): return f'<p class="muted small"><b>What this means:</b> {desc}<br><b>Example:</b> {example}</p>'
    form=f'''<div class="hero"><span class="badge">MY BUSINESS PLAN • UNLOCKED FOR TESTING</span><h1>Build Your Professional Business Plan</h1><p class="muted">Answer in your own words. You do not need formal business language. Each section explains what it means and gives an example. Your answers—not the examples—will be used to generate your professional 10–15 page Business Plan, Marketing Strategy and 90-Day Launch Plan.</p></div><form class="card" method="post">
    <h2>Contact & Business Overview</h2><label><b>Name</b></label><input class="input" name="name" value="{v('name')}"><label><b>Email</b></label><input class="input" type="email" name="email" value="{v('email')}"><label><b>Phone</b></label><input class="input" name="phone" value="{v('phone')}"><label><b>Preferred Method of Contact</b></label><input class="input" name="preferred_contact" value="{v('preferred_contact')}" placeholder="Email, Phone, Other"><label><b>Business Name (if registered)</b></label><input class="input" name="business_name" value="{v('business_name')}"><label><b>Type of Business</b></label><input class="input" name="business_type" value="{v('business_type')}" placeholder="LLC, Corporation, Nonprofit, Sole Proprietor, Partnership, Other"><label><b>Industry / Sector</b></label>{helpbox('The field your business operates in.','Wellness, beauty, food service, education, consulting, retail, technology.') }<input class="input" name="industry" value="{v('industry')}"><label><b>Business Stage</b></label><select class="input" name="business_stage"><option>{v('business_stage') or 'Idea Stage'}</option><option>Idea Stage</option><option>Startup (&lt;1 year)</option><option>Growing (1–3 years)</option><option>Established (3+ years)</option></select>
    <h2>Mission, Vision & Position</h2><label><b>Mission Statement</b></label>{helpbox('What is the purpose of your business, why does it exist, who does it serve and how?','Our mission is to provide accessible seasonal wellness experiences that help adults reconnect with rest, nature and intentional living.') }<textarea class="input" name="mission">{v('mission')}</textarea><label><b>Vision Statement</b></label>{helpbox('What do you want the business to become or accomplish in the next 3–5 years?','Our vision is to become a trusted Michigan wellness destination serving thousands of guests through classes, private retreats and community experiences.') }<textarea class="input" name="vision">{v('vision')}</textarea><label><b>Core Values</b></label>{helpbox('The principles that guide your decisions and customer experience.','Integrity, community, sustainability, safety and personalized care.') }<textarea class="input" name="core_values">{v('core_values')}</textarea><label><b>Unique Selling Proposition (USP)</b></label>{helpbox('What makes your business different and why a customer should choose you.','Unlike large wellness centers, our experiences are small, seasonal and personally coordinated around each guest.') }<textarea class="input" name="usp">{v('usp')}</textarea>
    <h2>Goals & Needs</h2><label><b>Short-term business goals (6–12 months)</b></label>{helpbox('The specific results you want in the next year.','Publish the Hosted App, reach 100 paying customers, launch monthly classes and book 10 private retreats.') }<textarea class="input" name="short_goals">{v('short_goals')}</textarea><label><b>Long-term business goals (2–5 years)</b></label>{helpbox('How you want the business to grow over several years.','Expand to a second location, hire a small team and develop recurring membership revenue.') }<textarea class="input" name="long_goals">{v('long_goals')}</textarea><label><b>Biggest challenges or obstacles right now</b></label>{helpbox('Anything making growth difficult today.','Limited marketing budget, inconsistent bookings and not enough time to manage scheduling and promotion.') }<textarea class="input" name="challenges">{v('challenges')}</textarea><label><b>What do you hope to gain from a completed business plan?</b></label><input class="input" name="plan_goal" value="{v('plan_goal')}" placeholder="Funding, Expansion, Certification, Internal Strategy, Other">
    <h2>Financial Structure</h2><label><b>Do you currently have financial records?</b></label><input class="input" name="financial_records" value="{v('financial_records')}" placeholder="Yes, No, In Progress"><label><b>Estimated startup or growth budget</b></label>{helpbox('What you expect to spend to launch or expand.','Approximately $18,000 for equipment, insurance, marketing, software and initial supplies.') }<input class="input" name="budget" value="{v('budget')}"><label><b>Current or projected revenue sources</b></label>{helpbox('Every way the business makes or expects to make money.','Classes, private sessions, retreats, digital programs, products and memberships.') }<textarea class="input" name="revenue_sources">{v('revenue_sources')}</textarea><label><b>Financial areas where you need help</b></label><textarea class="input" name="financial_help" placeholder="Cash flow projections, Startup budget, Break-even analysis, Pricing structure, Funding strategies">{v('financial_help')}</textarea>
    <h2>Marketing & Growth</h2><label><b>Target audience / customer</b></label>{helpbox('Who is most likely to need, value and pay for your offer.','Adults 30–55 in Southeast Michigan who value wellness, nature, personal growth and personalized experiences.') }<textarea class="input" name="target_audience">{v('target_audience')}</textarea><label><b>Current marketing strategy</b></label>{helpbox('How customers currently discover and hear from your business.','Instagram, referrals, local events, Google Business Profile and partnerships with nearby wellness providers.') }<textarea class="input" name="marketing_strategy">{v('marketing_strategy')}</textarea><label><b>Marketing areas where you need help</b></label><textarea class="input" name="marketing_help" placeholder="Branding, digital marketing, community outreach, sales strategy">{v('marketing_help')}</textarea>
    <h2>Certifications & Compliance</h2><label><b>Do you need certifications for government contracts or awards?</b></label><input class="input" name="certification_need" value="{v('certification_need')}" placeholder="Yes, No, Unsure"><label><b>Certifications of interest</b></label><textarea class="input" name="certifications" placeholder="SAM.gov, MBE, WBE, DBE, Veteran-Owned, Other">{v('certifications')}</textarea>
    <h2>Grant & Funding Support</h2><label><b>Interested in grant-writing services?</b></label><input class="input" name="grant_interest" value="{v('grant_interest')}" placeholder="Yes, No, Maybe"><label><b>What type of funding are you seeking?</b></label>{helpbox('Describe the funding purpose and approximate need if known.','$25,000 startup capital for equipment, working capital and launch marketing.') }<textarea class="input" name="funding_type">{v('funding_type')}</textarea>
    <h2>Additional Information</h2><label><b>Anything else we should know about the business or vision?</b></label><textarea class="input" name="additional_info">{v('additional_info')}</textarea><label><b>How did you hear about us?</b></label><input class="input" name="heard_about" value="{v('heard_about')}"><div class="actions"><button class="out" name="action" value="save">Save & Continue Later</button><button class="btn" name="action" value="generate">Generate Professional Business Plan</button></div></form>'''
    return page('Business Plan Questionnaire',form,'business')

@app.route('/business-plan/generate')
@login_required
def business_plan_generate():
    u=current_user(); conn=db(); row=conn.execute('SELECT payload FROM business_plan_intake WHERE user_id=?',(u['id'],)).fetchone(); conn.close()
    if not row: flash('Complete and save the Business Plan questionnaire first.','info'); return redirect(url_for('startup'))
    answers=json.loads(row['payload']); plan,error=generate_business_plan_ai(answers)
    if error: flash(error,'error'); return redirect(url_for('business_plan'))
    marketing=extract_plan_subsection(plan,'Marketing Strategy','Operations Plan') or extract_plan_subsection(plan,'Marketing Strategy','Operations')
    launch=extract_plan_subsection(plan,'90-Day Launch Plan','Conclusion') or extract_plan_subsection(plan,'90-Day Action Priorities','Conclusion')
    conn=db(); v=conn.execute('SELECT COALESCE(MAX(version),0)+1 v FROM business_plans WHERE user_id=?',(u['id'],)).fetchone()['v']; conn.execute('''INSERT INTO business_plans(user_id,version,payload,document_text,marketing_text,launch_text,status,created_at) VALUES(?,?,?,?,?,?,?,?)''',(u['id'],v,json.dumps(answers),plan,marketing,launch,'Generated',now())); conn.commit(); conn.close(); notify(u['id'],'Business Plan Ready',f'Business Plan Version {v} is ready to view and download.',url_for('plan_versions')); flash(f'Professional Business Plan Version {v} generated and saved.','success'); return redirect(url_for('business_plan'))

